static System.Collections.Generic.IEnumerable<UnityEngine.GameObject> All(UnityEngine.SceneManagement.Scene s) => s.GetRootGameObjects().SelectMany(r => r.GetComponentsInChildren<UnityEngine.Transform>(true)).Select(t => t.gameObject);
var outp = new System.Collections.Generic.List<string>();
var allAssets = AssetDatabase.GetAllAssetPaths().Where(p => p.StartsWith("Assets/") && !p.EndsWith(".unity")).ToList();
foreach (var sp in new[]{"Assets/Scenes/Game.unity","Assets/Scenes/EditorTool.unity","Assets/Libs/Epic Toon FX/Demo/Scenes/Secrets/etfx_library.unity","Assets/Libs/Epic Toon FX/Demo/Scenes/etfx_missiles.unity","Assets/Libs/TutorialFadeImage/Demo/DemoScene.unity","Assets/Libs/Epic Toon FX/Demo/Scenes/etfx_explosions2.unity","Assets/Libs/Epic Toon FX/Demo/Scenes/etfx_maindemo.unity","Assets/Libs/Epic Toon FX/Demo/Scenes/etfx_emojis.unity","Assets/Libs/Epic Toon FX/Demo/Scenes/etfx_swordcombat.unity","Assets/Libs/Epic Toon FX/Demo/Scenes/etfx_explosions.unity","Assets/Libs/Epic Toon FX/Demo/Scenes/etfx_2ddemo.unity","Assets/Libs/Epic Toon FX/Demo/Scenes/etfx_combat.unity","Assets/Plugins/UniRx/Examples/Sample12Scene.unity","Assets/Libs/Epic Toon FX/Demo/Scenes/Secrets/etfx_videopreview.unity","Assets/Libs/Epic Toon FX/Demo/Scenes/etfx_magic.unity","Assets/Libs/AssetKits/ParticleImage/Demo/Scenes/APICall.unity","Assets/Libs/Le Tai's Asset/TrueShadow/Demo/Full Colors/Full Colors.unity","Assets/Plugins/UniRx/Examples/Sample13Scene.unity","Assets/Libs/Le Tai's Asset/TrueShadow/Demo/Inspiration/Inspirations.unity","Assets/Libs/Le Tai's Asset/TrueShadow/Demo/Symbols/Symbols.unity","Assets/Libs/Le Tai's Asset/TrueShadow/Demo/Neumorphism/Neumorphism.unity","Assets/Libs/Le Tai's Asset/TrueShadow/Demo/Quick Presets/Quick Presets.unity","Assets/Libs/Le Tai's Asset/TrueShadow/Demo/Swipe/Swipe.unity","Assets/Libs/Epic Toon FX/Demo/Scenes/etfx_fireworks.unity","Assets/Libs/Le Tai's Asset/TrueShadow/Demo/Custom Shadow Material/Custom Shadow Material.unity","Assets/Plugins/Zenject/OptionalExtras/SampleGame2 (Advanced)/Scenes/SpaceFighter.unity","Assets/Libs/AssetKits/ParticleImage/Demo/Scenes/WorldSpaceAttractor.unity","Assets/Libs/AssetKits/ParticleImage/Demo/Scenes/AlignToDirection.unity","Assets/Libs/AssetKits/ParticleImage/Demo/Scenes/CoinAttraction.unity","Assets/Libs/AssetKits/ParticleImage/Demo/Scenes/ConfettiBurst.unity","Assets/Libs/AssetKits/ParticleImage/Demo/Scenes/ConfettiFullscreen.unity","Assets/Libs/AssetKits/ParticleImage/Demo/Scenes/EnergySpread.unity","Assets/Libs/AssetKits/ParticleImage/Demo/Scenes/Highlight.unity","Assets/Libs/AssetKits/ParticleImage/Demo/Scenes/Masking.unity","Assets/Libs/AssetKits/ParticleImage/Demo/Scenes/Puff.unity","Assets/Libs/AssetKits/ParticleImage/Demo/Scenes/Scroll.unity","Assets/Libs/AssetKits/ParticleImage/Demo/Scenes/Slider.unity","Assets/Libs/AssetKits/ParticleImage/Demo/Scenes/UniformEmitter.unity","Assets/Plugins/Zenject/OptionalExtras/SampleGame1 (Beginner)/Asteroids.unity","Assets/Libs/Epic Toon FX/Demo/Scenes/etfx_powerups.unity","Assets/Libs/Epic Toon FX/Demo/Scenes/etfx_portals.unity","Assets/Libs/Epic Toon FX/Demo/Scenes/etfx_sparkles.unity","Assets/Libs/Tetra Attributes/Example/Example.unity","Assets/Plugins/Zenject/OptionalExtras/IntegrationTests/SceneTests/TestSceneContextEvents/TestSceneContextEvents.unity","Assets/Scenes/Init.unity","Assets/Libs/Epic Toon FX/Demo/ParticleEffectsShowcase/Scenes/PEDemoScene.unity","Assets/Libs/Epic Toon FX/Demo/Scenes/Secrets/etfx_singleeffect.unity","Assets/Plugins/Zenject/OptionalExtras/IntegrationTests/SceneTests/TestDestructionOrder/TestDestructionOrder1.unity","Assets/Plugins/Zenject/OptionalExtras/IntegrationTests/SceneTests/TestDestructionOrder/TestDestructionOrder2.unity","Assets/Plugins/Zenject/OptionalExtras/IntegrationTests/SceneContractTests/AutoLoader/Scene1.unity","Assets/Plugins/Zenject/OptionalExtras/IntegrationTests/SceneContractTests/AutoLoader/Scene2.unity","Assets/Plugins/Zenject/OptionalExtras/IntegrationTests/SceneContractTests/AutoLoader/Scene3.unity","Assets/Plugins/Zenject/OptionalExtras/IntegrationTests/SceneContractTests/Decorators/Scene1.unity","Assets/Plugins/Zenject/OptionalExtras/IntegrationTests/SceneContractTests/Decorators/Scene2.unity","Assets/Plugins/Zenject/OptionalExtras/IntegrationTests/SceneTests/TestDestructionOrder/EmptyScene.unity"}) {
  var s = UnityEditor.SceneManagement.EditorSceneManager.OpenScene(sp, UnityEditor.SceneManagement.OpenSceneMode.Single);
  var inst = All(s).Where(g => PrefabUtility.IsOutermostPrefabInstanceRoot(g)).GroupBy(g => AssetDatabase.GetAssetPath(PrefabUtility.GetCorrespondingObjectFromSource(g))).Where(g => g.Count() >= 5).OrderByDescending(g => g.Count()).ThenBy(g => g.Key).ToList();
  foreach (var g in inst) {
    var u = allAssets.Where(p => p != g.Key && AssetDatabase.GetDependencies(p, false).Contains(g.Key)).ToList();
    if (u.Count >= 1) { return "T3|" + sp + "|" + g.Key + "=" + g.Count() + "|" + string.Join(",", u); } }
  outp.Add(sp + ":" + inst.Count); }
return "none|" + string.Join(";", outp);